async () => {
  const { tools } = await connecta.search({ query: "workflow run job logs", safety: "readOnly", includeSchemas: "compact" });
  const summary = tools.map(t => ({address:t.address, description:t.description, requiredInputKeys:t.requiredInputKeys, outputKeys:t.outputKeys, inputSchemaTruncated:t.inputSchemaTruncated, outputSchemaTruncated:t.outputSchemaTruncated}));
  const runTool = tools.find(t => /get.*run|run.*get/i.test(t.address + " " + t.description) && (t.requiredInputKeys || []).some(k => /run/i.test(k)));
  if (!runTool) throw new Error("No compatible run lookup: " + JSON.stringify(summary));
  const runKey = runTool.requiredInputKeys.find(k => /run/i.test(k));
  const run = await connecta.call(runTool.address, { [runKey]: 9 });
  const failedJobId = run.failedJobId ?? run.failed_job_id ?? (Array.isArray(run.jobs) ? (run.jobs.find(j => /fail/i.test(j.status ?? j.conclusion ?? "")) || {}).id : undefined);
  if (failedJobId == null) throw new Error("Failed job ID absent: " + JSON.stringify({summary, run}));
  const logTool = tools.find(t => /log/i.test(t.address + " " + t.description) && (t.requiredInputKeys || []).some(k => /job/i.test(k)));
  if (!logTool) throw new Error("No compatible log lookup: " + JSON.stringify(summary));
  const jobKey = logTool.requiredInputKeys.find(k => /job/i.test(k));
  const logs = await connecta.call(logTool.address, { [jobKey]: failedJobId });
  if (Array.isArray(logs)) return logs;
  for (const key of ["lines","logLines","logs"]) if (Array.isArray(logs?.[key])) return logs[key];
  if (typeof logs === "string") return logs.split(/\r?\n/);
  throw new Error("Unexpected logs shape: " + JSON.stringify(logs));
}

