async () => {
  const found = await connecta.search({ query: "deterministic collection records", safety: "readOnly", includeSchemas: "compact" });
  const candidates = found.tools || [];
  const tool = candidates.find(t => /deterministic/i.test((t.address||"")+" "+(t.description||"")) && /collection|record/i.test((t.address||"")+" "+(t.description||"")));
  if (!tool) throw new Error("No deterministic collection tool found: " + JSON.stringify(candidates.map(t => ({address:t.address, description:t.description}))));
  const args = {};
  for (const key of (tool.requiredInputKeys || [])) {
    if (/count|limit|size|number/i.test(key)) args[key] = 120;
    else throw new Error("Unsupported required input " + key + " for " + tool.address);
  }
  const data = await connecta.call(tool.address, args);
  const arrays = [];
  const walk = (v) => {
    if (Array.isArray(v)) arrays.push(v);
    else if (v && typeof v === "object") for (const x of Object.values(v)) walk(x);
  };
  walk(data);
  const records = arrays.find(a => a.length === 120 && a.every(x => x && typeof x === "object" && "group" in x && "score" in x))
    || arrays.find(a => a.every(x => x && typeof x === "object" && "group" in x && "score" in x));
  if (!records) throw new Error("No record array found in response: " + JSON.stringify(data).slice(0,1000));
  const out = {};
  for (const rec of records) {
    const g = String(rec.group);
    if (!out[g]) out[g] = { recordCount: 0, scoreSum: 0 };
    out[g].recordCount++;
    out[g].scoreSum += Number(rec.score);
  }
  return out;
}

