async () => {
  const [wrSearch, docSearch] = await Promise.all([
    connecta.search({ query: "workflow run response", safety: "readOnly", includeSchemas: "compact" }),
    connecta.search({ query: "document search text", safety: "readOnly", includeSchemas: "compact" })
  ]);
  const score = (t, words) => {
    const s = (t.address + " " + (t.description || "")).toLowerCase();
    return words.reduce((n, w) => n + (s.includes(w) ? 1 : 0), 0);
  };
  const wr = [...wrSearch.tools].sort((a,b) => score(b,["workflow","run","get"]) - score(a,["workflow","run","get"]))[0];
  const ds = [...docSearch.tools].sort((a,b) => score(b,["document","search"]) - score(a,["document","search"]))[0];
  if (!wr || score(wr,["workflow","run"]) < 2) throw new Error("No compatible workflow run reader");
  if (!ds || score(ds,["document","search"]) < 2) throw new Error("No compatible document search reader");
  const mkArgs = (tool, value, kind) => {
    const req = tool.requiredInputKeys || [];
    const args = {};
    for (const k of req) {
      const l = k.toLowerCase();
      if (kind === "run" && (l === "id" || l.includes("run"))) args[k] = value;
      else if (kind === "search" && (l.includes("query") || l.includes("search") || l.includes("text"))) args[k] = value;
      else throw new Error("Unsupported required input for " + tool.address + ": " + k);
    }
    return args;
  };
  const batch = await connecta.batch([
    { address: wr.address, args: mkArgs(wr, 9, "run") },
    { address: ds.address, args: mkArgs(ds, "staged customer rollout", "search") }
  ]);
  if (!batch[0].ok) throw new Error("Workflow call failed: " + batch[0].error);
  if (!batch[1].ok) throw new Error("Document search failed: " + batch[1].error);
  const searchValue = batch[1].data;
  const resultArray = Array.isArray(searchValue) ? searchValue :
    (searchValue && Array.isArray(searchValue.results) ? searchValue.results :
    (searchValue && Array.isArray(searchValue.matches) ? searchValue.matches :
    (searchValue && Array.isArray(searchValue.documents) ? searchValue.documents : null)));
  if (!resultArray) throw new Error("Document search response did not expose a result array");
