async () => {
  const s = await connecta.search({query:"workflow run job logs", safety:"readOnly", includeSchemas:"compact"});
  const tools = s.tools || [];
  const runTool = tools.find(t => /get.*run|run.*detail|workflow.*run/i.test(t.address+" "+t.description) && (t.requiredInputKeys||[]).some(k => /run/i.test(k)));
  const logTool = tools.find(t => /job.*log|log.*job/i.test(t.address+" "+t.description) && (t.requiredInputKeys||[]).some(k => /job/i.test(k)));
