  const run = await connecta.call(runTool.address, {[runKey]:9});
  let failedId = run.failedJobId ?? run.failed_job_id;
  if (failedId == null && Array.isArray(run.jobs)) {
    const j = run.jobs.find(x => /fail/i.test(String(x.conclusion ?? x.status)));
    failedId = j && (j.id ?? j.jobId ?? j.job_id);
  }
