async () => {
  const s = await connecta.search({query:"deterministic collection records", safety:"readOnly", includeSchemas:"compact"});
  const candidates = s.tools.filter(t => {
    const x = (t.address+" "+(t.description||"")).toLowerCase();
    return x.includes("record") && (x.includes("collection") || x.includes("deterministic"));
  });
  if (!candidates.length) throw new Error("No compatible collection records tool");
  const t = candidates.find(t => (t.outputKeys||[]).some(k => /record|item|data/i.test(k))) || candidates[0];
  const args = {};
  for (const k of (t.requiredInputKeys||[])) {
    if (/limit|count|size/i.test(k)) args[k] = 120;
    else if (/collection|dataset|name/i.test(k)) args[k] = "deterministic";
    else throw new Error("Unsupported required input: "+k);
  }
  const raw = await connecta.call(t.address,args);
  const arr = Array.isArray(raw) ? raw : (raw.records || raw.items || raw.data || raw.results);
  if (!Array.isArray(arr)) throw new Error("Records array not found");
  const out = {};
  for (const rec of arr) {
    const g = rec.group ?? rec.groupName ?? rec.category;
    const score = rec.score;
    if (g == null || typeof score !== "number") throw new Error("Unexpected record shape");
    if (!out[g]) out[g] = {recordCount:0, scoreSum:0};
    out[g].recordCount++;
    out[g].scoreSum += score;
  }
  return out;
}

