async () => {
  const { tools } = await connecta.search({ query: "list routing incidents", safety: "readOnly", includeSchemas: "compact" });
  const candidates = tools.filter(t => /incident/i.test(t.address + " " + (t.description || "")));
  if (!candidates.length) throw new Error("No incident listing tool found");
  const t = candidates.find(t => /list|search|get.*incident/i.test(t.address + " " + (t.description || "")) && (t.requiredInputKeys || []).every(k => ["status","state","active"].includes(k))) || candidates[0];
  const args = {};
  for (const k of (t.requiredInputKeys || [])) {
    if (k === "status" || k === "state") args[k] = "active";
    else if (k === "active") args[k] = true;
    else throw new Error("Unsupported required input: " + k);
  }
  const data = await connecta.call(t.address, args);
  const rows = Array.isArray(data) ? data : (data.incidents || data.results || data.items || []);
  const active = rows.filter(x => {
    const s = String(x.status ?? x.state ?? "").toLowerCase();
    return x.active === true || s === "active" || s === "open" || s === "triggered" || s === "investigating" || s === "identified" || s === "monitoring";
  });
  const routing = active.filter(x => /routing/i.test(String(x.type ?? x.category ?? x.service ?? x.title ?? x.name ?? "")));
  const chosen = routing.length ? routing : active;
  return { count: chosen.length, titles: chosen.map(x => String(x.title ?? x.name ?? x.summary ?? "")) };
}

